      {"title": "Magic Resistance", "text": "The dryad has advantage on saving throws against spells and other magical effects."},
      {"title": "Speak with Beasts and Plants", "text": "The dryad can communicate with beasts and plants as if they shared a language."},
      {"title": "Tree Stride", "text": "Once on her turn, the dryad can use 10 ft. of her movement to step magically into one living tree within her reach and emerge from a second living tree within 60 ft. of the first tree, appearing in an unoccupied space within 5 ft. of the second tree. Both trees must be large or bigger."}
