      {"title": "Multiattack", "text": "The gibbering mouther makes one bite attack and, if it can, uses its Blinding Spittle."},
      {"title": "Bites", "text": "Melee Weapon Attack: +2 to hit, reach 5 ft., one creature. Hit: 17 (5d6) piercing damage. If the target is Medium or smaller, it must succeed on a DC 10 Strength saving throw or be knocked prone. If the target is killed by this damage, it is absorbed into the mouther."},
      {"title": "Blinding Spittle (Recharge 5-6)", "text": "The mouther spits a chemical glob at a point it can see within 15 feet of it. The glob explodes in a blinding flash of light on impact. Each creature within 5 feet of the flash must succeed on a DC 13 Dexterity saving throw or be blinded until the end of the mouther's next turn."}
